import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, Vector3 } = ctx.THREE;

  // Create local container
  const container = new Group();

  // Color constants
  const ink = new Color('#16161d');
  const paper = new Color('#e8ecf2');
  const accent = new Color('#ff2a38');
  const surface = new Color('#0b0b10');

  // Grounding Backdrop (Stage)
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.85
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // Gradient vertical slash / accent bar
  const accentBarGeom = new PlaneGeometry(0.04, 1.2);
  const accentBarMat = new MeshBasicNodeMaterial({ color: accent });
  const accentBar = new Mesh(accentBarGeom, accentBarMat);
  accentBar.position.set(-1.1, 0, 0.01);
  container.add(accentBar);

  // Main Card Body (Machined-Metal visual style, dark ground)
  const cardGeom = new PlaneGeometry(2.4, 1.4);
  const cardMat = new MeshBasicNodeMaterial({
    color: ink,
    transparent: true,
    opacity: 0.95
  });
  const cardMesh = new Mesh(cardGeom, cardMat);
  cardMesh.position.set(0, 0, 0);
  container.add(cardMesh);

  // Outline/Border for "accent edge on focus" visual
  const borderGeom = new PlaneGeometry(2.42, 1.42);
  const borderMat = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.15
  });
  const borderMesh = new Mesh(borderGeom, borderMat);
  borderMesh.position.set(0, 0, -0.01);
  container.add(borderMesh);

  // Load configured image asset
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      cardMat.color = new Color('#ffffff');
      cardMat.map = texture;
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed loading image asset texture, falling back to default styling.', err);
    });
  }

  // Text Rendering from config.textContent or visualSpec fallback
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textVal = textItems[0]?.text ?? "Journal 3";

  // Create title via fontAtlas
  const labelText = ctx.fontAtlas.createText(textVal, {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left'
  });
  labelText.position.set(-0.9, -0.05, 0.05);
  container.add(labelText);

  // Timeline & Interaction setup
  let hoverTimeline = null;
  let clickTimeline = null;

  // Interaction: Hover Lift + Accent Contrast Highlight
  const onPointerOver = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(container.position, {
      z: 0.15, // Rise-in (subtle 0.15 units)
      duration: 0.3,
      ease: 'power3.out'
    });
    hoverTimeline.to(borderMat, {
      opacity: 0.8,
      duration: 0.3
    }, 0);
    hoverTimeline.to(accentBar.position, {
      x: -1.15,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  const onPointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(container.position, {
      z: 0.06, // Reset to design spec position
      duration: 0.4,
      ease: 'power2.out'
    });
    hoverTimeline.to(borderMat, {
      opacity: 0.15,
      duration: 0.4
    }, 0);
    hoverTimeline.to(accentBar.position, {
      x: -1.1,
      duration: 0.4,
      ease: 'power2.out'
    }, 0);
  };

  // Interaction: Click with press-down and emit navigation sequence
  const onPointerDown = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();
    clickTimeline.to(container.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)'
    });
  };

  const onPointerUp = () => {
    if (clickTimeline) clickTimeline.kill();
    clickTimeline = gsap.timeline();
    clickTimeline.to(container.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2,
      ease: 'power2.out'
    });
    ctx.emit('hub-journal.select', { id: 'journal-3', label: textVal });
  };

  // Attach Event Handlers
  container.userData = {
    handlers: {
      pointerover: onPointerOver,
      pointerout: onPointerOut,
      pointerdown: onPointerDown,
      pointerup: onPointerUp
    },
    cleanup: () => {
      if (hoverTimeline) hoverTimeline.kill();
      if (clickTimeline) clickTimeline.kill();
      backdropGeom.dispose();
      backdropMat.dispose();
      accentBarGeom.dispose();
      accentBarMat.dispose();
      cardGeom.dispose();
      cardMat.dispose();
      borderGeom.dispose();
      borderMat.dispose();
    }
  };

  return container;
}
